func atCode(al *port.Cells, n int32) int32 {
	// The code of the verdict on the n rows from row 0, 0 when it is below `align-min` or none.
	var v int32 = align.AlJudge(al, 0, n)
	if align.AlConf(v) < align.AlMin() {
		return 0
	}
	return align.AlCode(v)
}

func TestEveryRowOfTheTable(emonT *testing.T) {
	var al *port.Cells = port.NewCells()
	// justify: four lines flush at both edges (a hair off), the last flush at the start and short.
	align.AlLine(al, 0, 40, 1000, 0)
	align.AlLine(al, 20, 0, 1000, 0)
	align.AlLine(al, 0, 30, 1000, 0)
	align.AlLine(al, 10, 5400, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlJustify(), "justify")
	port.CellsDrop(al, 0)
	// start: every S at the edge, the end edge ragged.
	align.AlLine(al, 0, 1500, 1000, 0)
	align.AlLine(al, 0, 800, 1000, 0)
	align.AlLine(al, 0, 3000, 1000, 0)
	align.AlLine(al, 0, 6000, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlStart(), "start")
	port.CellsDrop(al, 0)
	// end: every E at the edge, the start edge ragged.
	align.AlLine(al, 1500, 0, 1000, 0)
	align.AlLine(al, 800, 0, 1000, 0)
	align.AlLine(al, 3000, 0, 1000, 0)
	align.AlLine(al, 600, 0, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlEnd(), "end")
	port.CellsDrop(al, 0)
	// center: S = E on every line, and the lines differ.
	align.AlLine(al, 1000, 1000, 1000, 0)
	align.AlLine(al, 2500, 2500, 1000, 0)
	align.AlLine(al, 500, 500, 1000, 0)
	align.AlLine(al, 3000, 3100, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlCenter(), "center")
	port.CellsDrop(al, 0)
	// a first-line indent comes out of line 1's S: the block is start, not none.
	align.AlLine(al, 1500, 1800, 1000, 0)
	align.AlLine(al, 0, 900, 1000, 0)
	align.AlLine(al, 0, 2600, 1000, 0)
	align.AlLine(al, 0, 5000, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlStart(), "an indented first line")
	port.CellsDrop(al, 0)
	// a justified block with an indented first line is justify.
	align.AlLine(al, 1500, 0, 1000, 0)
	align.AlLine(al, 0, 0, 1000, 0)
	align.AlLine(al, 0, 0, 1000, 0)
	align.AlLine(al, 0, 4000, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), model.AlJustify(), "justify with an indent")
}

func TestWhatHasNoVerdict(emonT *testing.T) {
	var al *port.Cells = port.NewCells()
	// Two lines, both flush at both edges: not enough to say justify (one non-last line), and not start, end or center.
	align.AlLine(al, 0, 0, 1000, 0)
	align.AlLine(al, 0, 4000, 1000, 0)
	port.AssertEq(emonT, atCode(al, 2), 0, "two lines")
	port.CellsDrop(al, 0)
	// A block that wanders: S and E both vary, S - E does not hold.
	align.AlLine(al, 0, 3000, 1000, 0)
	align.AlLine(al, 2000, 100, 1000, 0)
	align.AlLine(al, 700, 4000, 1000, 0)
	align.AlLine(al, 0, 100, 1000, 0)
	port.AssertEq(emonT, atCode(al, 4), 0, "no pattern")
	port.CellsDrop(al, 0)
	port.AssertEq(emonT, align.AlJudge(al, 0, 0), 0, "no lines")
}

func TestASingleLine(emonT *testing.T) {
	var al *port.Cells = port.NewCells()
	// Centred: S and E at least four t, and within t of each other.
	align.AlLine(al, 5000, 5100, 1000, 0)
	port.AssertEq(emonT, atCode(al, 1), model.AlCenter(), "a centred line")
	port.CellsDrop(al, 0)
	// At the end edge, started two body sizes in.
	align.AlLine(al, 9000, 0, 1000, 0)
	port.AssertEq(emonT, atCode(al, 1), model.AlEnd(), "a line at the end edge")
	port.CellsDrop(al, 0)
	// At the end edge but started only a body size in: an indented line that happens to fill its row.
	align.AlLine(al, 1200, 0, 1000, 0)
	port.AssertEq(emonT, atCode(al, 1), 0, "an indented full line is not right-aligned")
	port.CellsDrop(al, 0)
	// Flush at the start: `start`, but below `align-min`, for the second pass (the class) to decide.
	align.AlLine(al, 0, 5000, 1000, 0)
	port.AssertEq(emonT, align.AlCode(align.AlJudge(al, 0, 1)), model.AlStart(), "a flush-start line, tentatively start")
	port.AssertEq(emonT, atCode(al, 1), 0, "and not written on its own")
}

func TestTheSecondPassFollowsTheStyleClass(emonT *testing.T) {
	var al *port.Cells = port.NewCells()
	var cl *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	// Block 1: a start block of 4 lines in the 10 pt class; block 2: a single flush-start line of the same class
	// (start, it follows its peers); block 3: a single flush-start line of 20 pt, a class with no multi-line block
	// (a heading: start); block 4: a justified block of 4 lines in the 9 pt bold class and block 5 a single
	// flush-start line of that class (the last line of a justified block, perhaps: none); block 6: a centred line.
	var b1 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var b2 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var b3 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var b4 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var b5 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var b6 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	align.AlLine(al, 0, 1500, 1000, 0)
	align.AlLine(al, 0, 800, 1000, 0)
	align.AlLine(al, 0, 3000, 1000, 0)
	align.AlLine(al, 0, 6000, 1000, 0)
	align.AlMark(al, b1)
	align.AlLine(al, 0, 4000, 1000, 0)
	align.AlMark(al, b2)
	align.AlLine(al, 0, 4000, 2000, 0)
	align.AlMark(al, b3)
	align.AlLine(al, 0, 40, 900, 1)
	align.AlLine(al, 20, 0, 900, 1)
	align.AlLine(al, 0, 30, 900, 1)
	align.AlLine(al, 10, 5400, 900, 1)
	align.AlMark(al, b4)
	align.AlLine(al, 0, 4000, 900, 1)
	align.AlMark(al, b5)
	align.AlLine(al, 5000, 5100, 1000, 0)
	align.AlMark(al, b6)
	port.AssertEq(emonT, align.AlPass(nodes, attrs, al, cl), 5, "five blocks got an align")
	port.AssertEq(emonT, model.NodeSub(nodes, b1), model.AlStart(), "the multi-line start block")
	port.AssertEq(emonT, model.NodeSub(nodes, b2), model.AlStart(), "a single line follows a class of start blocks")
	port.AssertEq(emonT, model.NodeSub(nodes, b3), model.AlStart(), "a single line in a class with no multi-line block")
	port.AssertEq(emonT, model.NodeSub(nodes, b4), model.AlJustify(), "the justified block")
	port.AssertEq(emonT, model.NodeSub(nodes, b5), 0, "a single line in a class of justified blocks gets none")
	port.AssertEq(emonT, model.NodeSub(nodes, b6), model.AlCenter(), "a centred line")
}
